CREATE OR REPLACE FUNCTION public."B36_execution_binding"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r "OwnerReportRun"; root_xid xid;
BEGIN
 IF TG_OP = 'UPDATE' THEN
  IF (NEW."ownerReportRunId",NEW."ownerReportSlotKey") IS DISTINCT FROM
     (OLD."ownerReportRunId",OLD."ownerReportSlotKey") THEN
   RAISE EXCEPTION 'B36 execution binding immutable; historical promotion forbidden' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF OLD."ownerReportRunId" IS NOT NULL AND EXISTS (
   SELECT 1 FROM "OwnerReportRun" WHERE id=OLD."ownerReportRunId" AND "auditRetentionUntil">clock_timestamp()
  ) THEN RAISE EXCEPTION 'B36 durable execution retention' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF NEW."ownerReportRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO r FROM "OwnerReportRun" WHERE id=NEW."ownerReportRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "OwnerReportRun" WHERE id=NEW."ownerReportRunId" AND "tenantId"=NEW."tenantId";
 -- New slots can only join the transaction that first inserts the immutable root.
 IF r.id IS NULL OR root_xid IS DISTINCT FROM pg_current_xact_id()::xid
  OR r."intentEncrypted" IS NULL OR NEW.state <> 'READY'
  OR NEW."intentExpiresAt" IS DISTINCT FROM r."expiresAt"
  OR NEW."dryRun" OR NEW."policyDecision" <> 'ALLOW' THEN
  RAISE EXCEPTION 'B36 atomic accepted report admission required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."B36_report_immutable"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NEW."intentEncrypted" IS NULL OR length(NEW."intentEncrypted") = 0 THEN
   RAISE EXCEPTION 'B36 recoverable immutable plan required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF OLD."auditRetentionUntil" > clock_timestamp() THEN
   RAISE EXCEPTION 'B36 report identity retention' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW."intentEncrypted" IS NULL AND OLD."intentEncrypted" IS NOT NULL
  AND OLD."payloadRetentionUntil" <= clock_timestamp()
  AND (to_jsonb(NEW) - 'intentEncrypted') = (to_jsonb(OLD) - 'intentEncrypted') THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'B36 immutable report identity/manifest' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R06_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "OperationalAlertRun"%ROWTYPE; root_xid xid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."operationalAlertRunId" IS NOT NULL THEN RAISE EXCEPTION 'R06 slot tombstone retained' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."operationalAlertRunId" IS DISTINCT FROM OLD."operationalAlertRunId" OR NEW."operationalAlertSlotKey" IS DISTINCT FROM OLD."operationalAlertSlotKey" THEN
   RAISE EXCEPTION 'R06 immutable slot binding' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."operationalAlertRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO root FROM "OperationalAlertRun" WHERE id=NEW."operationalAlertRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "OperationalAlertRun" WHERE id=root.id;
 IF root.id IS NULL OR root_xid<>pg_current_xact_id()::xid OR root."intentEncrypted" IS NULL OR NEW.state<>'READY'
  OR NEW."policyDecision"<>'ALLOW' OR NEW."dryRun" OR NEW."intentExpiresAt" IS DISTINCT FROM root."expiresAt"
  OR (root."alertType"='staff_shift_reminder' AND (NEW.capability<>'communication.appointment-reminders.execute.v1' OR NEW."actionClass"<>'deliver_appointment_reminder'))
  OR (root."alertType"='wanted_slot_admin_notice' AND (NEW.capability<>'communication.business-alerts.execute.v1' OR NEW."actionClass"<>'deliver_business_alert')) THEN
  RAISE EXCEPTION 'R06 exact type / complete same-transaction admission required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R08_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_execution text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."nativeFeedbackRequestId" IS NOT NULL THEN RAISE EXCEPTION 'R08 delivery evidence retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."nativeFeedbackRequestId" IS DISTINCT FROM OLD."nativeFeedbackRequestId" OR NEW."nativeFeedbackRevisionId" IS DISTINCT FROM OLD."nativeFeedbackRevisionId" OR NEW."nativeFeedbackSlotKey" IS DISTINCT FROM OLD."nativeFeedbackSlotKey" THEN RAISE EXCEPTION 'R08 immutable delivery slot binding' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF NEW."nativeFeedbackRequestId" IS NULL THEN RETURN NEW; END IF;
 IF NEW."nativeFeedbackRevisionId" IS NULL THEN
  SELECT "requestExecutionId" INTO parent_execution FROM "NativeFeedbackRequest" WHERE id=NEW."nativeFeedbackRequestId" AND "tenantId"=NEW."tenantId" AND "planEncrypted" IS NOT NULL;
 ELSE
  SELECT "executionId" INTO parent_execution FROM "NativeFeedbackRevision" WHERE id=NEW."nativeFeedbackRevisionId" AND "tenantId"=NEW."tenantId" AND "requestId"=NEW."nativeFeedbackRequestId" AND "planEncrypted" IS NOT NULL AND kind='response';
 END IF;
 IF parent_execution IS NULL OR NEW.state<>'READY' OR NEW."dryRun" OR NEW."policyDecision"<>'ALLOW' OR NOT EXISTS (SELECT 1 FROM "ActionExecution" WHERE id=parent_execution AND "tenantId"=NEW."tenantId" AND state='SUCCEEDED') THEN
  RAISE EXCEPTION 'R08 confirmed parent and complete slot admission required' USING ERRCODE='23514';
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R08_revision_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "NativeFeedbackRequest"%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R08 response tombstone retained' USING ERRCODE='23514'; END IF;
 SELECT * INTO root FROM "NativeFeedbackRequest" WHERE id=NEW."requestId" AND "tenantId"=NEW."tenantId" FOR UPDATE;
 IF TG_OP='INSERT' THEN
  IF root.id IS NULL OR root."clientId"<>NEW."clientId" OR NEW.version<>root."latestResponseVersion"+1
   OR (NEW.kind='response' AND NEW."createdAt">root."expiresAt") OR NEW."planEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL
   OR NOT EXISTS (SELECT 1 FROM "ActionExecution" e WHERE e.id=NEW."executionId" AND e."tenantId"=NEW."tenantId" AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND e."actionClass"=CASE WHEN NEW.kind='withdraw' THEN 'withdraw_native_feedback' ELSE 'submit_native_feedback_revision' END)
   OR NOT EXISTS (SELECT 1 FROM "ActionExecution" WHERE id=root."requestExecutionId" AND "tenantId"=root."tenantId" AND state='SUCCEEDED') THEN
   RAISE EXCEPTION 'R08 exact admitted Client response / current revision required' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."commentEncrypted" IS NULL AND NEW."planEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['commentEncrypted','planEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['commentEncrypted','planEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'NativeFeedbackRevision',OLD.id,OLD."planHash",root."retentionUntil",'purge_native_feedback_payloads','native-feedback-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."executionId" OR "nativeFeedbackRevisionId"=OLD.id))) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R08 immutable response / exact payload claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R08_revision_projection_receipt"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "NativeFeedbackRequest"%ROWTYPE; latest "NativeFeedbackRevision"%ROWTYPE;
BEGIN
 SELECT * INTO root FROM "NativeFeedbackRequest" WHERE id=NEW."requestId" AND "tenantId"=NEW."tenantId";
 SELECT * INTO latest FROM "NativeFeedbackRevision" WHERE "requestId"=NEW."requestId" AND "tenantId"=NEW."tenantId" ORDER BY version DESC LIMIT 1;
 IF root."latestResponseVersion"<>latest.version OR root.revision<>latest.version OR
  root.state<>(CASE WHEN latest.kind='withdraw' THEN 'WITHDRAWN' ELSE 'RESPONDED' END) THEN
  RAISE EXCEPTION 'R08 accepted revision and exact current projection must commit together' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R09_comment_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE ref text; parent "PublicCommunityComment"%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R09 source and moderation tombstones retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW."authorEncrypted" IS NULL OR NEW."textEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL OR NEW.revision<>0 THEN
   RAISE EXCEPTION 'R09 immutable initial content required' USING ERRCODE='23514';
  END IF;
  IF NEW."sourceKind"='GUEST' THEN
   IF NEW.status<>'PENDING' OR NEW."lastModerationExecutionId" IS NOT NULL THEN RAISE EXCEPTION 'R09 guest source cannot publish itself' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT * INTO parent FROM "PublicCommunityComment" WHERE id=NEW."parentCommentId" AND "tenantId"=NEW."tenantId" FOR SHARE;
   IF parent.id IS NULL OR parent.status<>'APPROVED' OR parent."publicationKey"<>NEW."publicationKey" OR NEW.status<>'APPROVED' THEN
    RAISE EXCEPTION 'R09 reply exact approved parent required' USING ERRCODE='23514';
   END IF;
   ref=NEW."creationExecutionId";
  END IF;
 ELSIF NEW."authorEncrypted" IS NULL AND NEW."textEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['authorEncrypted','textEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['authorEncrypted','textEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'PublicCommunityComment',OLD.id,OLD."contentHash",OLD."retentionUntil",'purge_public_community_payloads','public-community-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY_REMOVE(ARRAY[OLD."creationExecutionId",OLD."lastModerationExecutionId"],NULL)) THEN RETURN NEW;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','revision','lastModerationExecutionId'])<>(to_jsonb(OLD)-ARRAY['status','revision','lastModerationExecutionId'])
   OR NEW.revision<>OLD.revision+1 OR NEW."lastModerationExecutionId" IS NULL OR NEW."lastModerationExecutionId" IS NOT DISTINCT FROM OLD."lastModerationExecutionId" THEN
   RAISE EXCEPTION 'R09 immutable content / explicit moderation CAS required' USING ERRCODE='23514';
  END IF;
  ref=NEW."lastModerationExecutionId";
 END IF;
 IF ref IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
  WHERE e.id=ref AND e."tenantId"=NEW."tenantId" AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
   AND e."actionClass"=CASE WHEN TG_OP='INSERT' THEN 'publish_public_community_reply' ELSE 'moderate_public_community_comment' END
   AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator')) THEN
  RAISE EXCEPTION 'R09 exact human moderator execution required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R09_interaction_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'R09 immutable anonymous source fact' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('r09/'||NEW."tenantId"||'/'||NEW."sourceGatewayId"||'/'||NEW."publicationKey"||'/'||NEW."visitorSubjectHash"||'/'||NEW.kind,0));
 SELECT COALESCE(max(version),0) INTO previous FROM "PublicCommunityInteraction" WHERE "tenantId"=NEW."tenantId" AND "sourceGatewayId"=NEW."sourceGatewayId" AND "publicationKey"=NEW."publicationKey" AND "visitorSubjectHash"=NEW."visitorSubjectHash" AND kind=NEW.kind;
 IF NEW."expectedVersion"<>previous THEN RAISE EXCEPTION 'R09 stale source projection version' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R11_config_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous "TenantBusinessConfigurationRevision"%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW."encryptedContent" IS NULL OR length(NEW."encryptedContent")=0 OR NOT EXISTS (
   SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId" JOIN "ActionExecution" e ON e.id=NEW."actionExecutionId" AND e."tenantId"=NEW."tenantId"
   WHERE m.id=NEW."actorMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."actorUserId"
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner')
    AND e."actorUserId"=NEW."actorUserId" AND e."actionClass"='update_tenant_business_configuration'
    AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW') THEN
   RAISE EXCEPTION 'R11 exact admitted actor/configuration required' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r11/'||NEW."tenantId"||'/'||NEW.namespace,0));
  SELECT * INTO previous FROM "TenantBusinessConfigurationRevision" WHERE "tenantId"=NEW."tenantId" AND namespace=NEW.namespace ORDER BY revision DESC LIMIT 1;
  IF (previous.id IS NULL AND (NEW.revision<>1 OR NEW."previousRevisionId" IS NOT NULL)) OR
    (previous.id IS NOT NULL AND (NEW."previousRevisionId" IS DISTINCT FROM previous.id OR NEW.revision<>previous.revision+1)) THEN
   RAISE EXCEPTION 'R11 stale namespace predecessor' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD."encryptedContent" IS NOT NULL AND NEW."encryptedContent" IS NULL
  AND (to_jsonb(NEW)-'encryptedContent')=(to_jsonb(OLD)-'encryptedContent')
  AND EXISTS (SELECT 1 FROM "TenantBusinessConfigurationRevision" r WHERE r."tenantId"=OLD."tenantId" AND r.namespace=OLD.namespace AND r.revision>OLD.revision)
  AND "RC_payload_claim"(OLD."tenantId",'TenantBusinessConfigurationRevision',OLD.id,OLD."contentHash",OLD."createdAt"+interval '365 days','purge_superseded_business_configuration_payloads','package5.r11.business-configuration-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY[OLD."actionExecutionId"])
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R11 append-only configuration / scoped superseded payload claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R12_attachment_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE exec text; msg "TeamMessage"%ROWTYPE; deadline timestamptz;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R12 attachment tombstone retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'RESERVED' OR NEW.revision<>0 OR NEW."finalizeExecutionId" IS NOT NULL OR NEW."actualSize" IS NOT NULL OR NEW."storageReceiptHash" IS NOT NULL OR NEW."mediaExpiresAt" IS NOT NULL OR NEW."payloadErasedAt" IS NOT NULL OR NEW."filenameEncrypted" IS NULL THEN RAISE EXCEPTION 'R12 reservation before publish required' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
   WHERE e.id=NEW."reserveExecutionId" AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."ownerUserId" AND e."actionClass"='reserve_team_attachment' AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RAISE EXCEPTION 'R12 canonical current reservation owner required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['finalizeExecutionId','actualSize','state','revision','mediaExpiresAt','storageReceiptHash','payloadErasedAt','lastObservedAt','filenameEncrypted'])<>(to_jsonb(OLD)-ARRAY['finalizeExecutionId','actualSize','state','revision','mediaExpiresAt','storageReceiptHash','payloadErasedAt','lastObservedAt','filenameEncrypted'])
  OR NEW.revision<>OLD.revision+1 OR (OLD."finalizeExecutionId" IS NOT NULL AND NEW."finalizeExecutionId" IS DISTINCT FROM OLD."finalizeExecutionId") THEN RAISE EXCEPTION 'R12 immutable upload intent / CAS required' USING ERRCODE='23514'; END IF;
 SELECT * INTO msg FROM "TeamMessage" WHERE "attachmentId"=OLD.id AND "tenantId"=OLD."tenantId";
 deadline=CASE WHEN msg.id IS NULL THEN OLD."uploadExpiresAt" ELSE LEAST(msg."createdAt"+interval '48 hours',COALESCE(msg."withdrawnAt",msg."createdAt"+interval '48 hours')) END;
 IF NEW.state='ERASED' AND OLD.state<>'ERASED' AND NEW."filenameEncrypted" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND NEW."actualSize" IS NOT DISTINCT FROM OLD."actualSize" AND NEW."mediaExpiresAt" IS NOT DISTINCT FROM OLD."mediaExpiresAt" AND NEW."storageReceiptHash" IS NOT DISTINCT FROM OLD."storageReceiptHash"
  AND "RC_payload_claim"(OLD."tenantId",'TeamAttachment',OLD.id,OLD."contentSha256",deadline,'purge_team_attachment_payloads','team-lifecycle-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."reserveExecutionId" OR id=OLD."finalizeExecutionId" OR id=msg."sendExecutionId" OR id=msg."withdrawalExecutionId" OR "teamMessageId"=msg.id))) THEN RETURN NEW; END IF;
 IF NEW."filenameEncrypted" IS DISTINCT FROM OLD."filenameEncrypted" OR NEW."payloadErasedAt" IS DISTINCT FROM OLD."payloadErasedAt" THEN RAISE EXCEPTION 'R12 exact attachment payload claim required' USING ERRCODE='23514'; END IF;
 IF OLD.state='SEALED' AND NEW.state='BOUND' AND msg.id IS NOT NULL AND NEW."mediaExpiresAt"=msg."createdAt"+interval '48 hours'
  AND NEW."actualSize" IS NOT DISTINCT FROM OLD."actualSize" AND NEW."storageReceiptHash" IS NOT DISTINCT FROM OLD."storageReceiptHash"
  AND EXISTS (SELECT 1 FROM "TeamMessage" WHERE id=msg.id AND xmin=pg_current_xact_id()::xid) THEN RETURN NEW; END IF;
 IF OLD.state='RESERVED' AND NEW.state IN ('RESERVED','SEALED') AND NEW."finalizeExecutionId" IS NOT NULL AND NEW."mediaExpiresAt" IS NULL
  AND EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
   WHERE e.id=NEW."finalizeExecutionId" AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."ownerUserId" AND e."actionClass"='finalize_team_attachment'
    AND e.state IN ('READY','EXECUTING','UNKNOWN','SUCCEEDED') AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R12 canonical reservation/finalization/binding transition required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."R12_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."teamMessageId" IS NOT NULL THEN RAISE EXCEPTION 'R12 delivery evidence retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."teamMessageId" IS DISTINCT FROM OLD."teamMessageId" OR NEW."teamMessageSlotKey" IS DISTINCT FROM OLD."teamMessageSlotKey" THEN RAISE EXCEPTION 'R12 immutable delivery slot binding' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF NEW."teamMessageId" IS NULL THEN RETURN NEW; END IF;
 IF NEW.state<>'READY' OR NEW."dryRun" OR NEW."policyDecision"<>'ALLOW' OR NOT EXISTS (
  SELECT 1 FROM "TeamMessage" m JOIN "ActionExecution" e ON e.id=m."sendExecutionId" AND e."tenantId"=m."tenantId"
  WHERE m.id=NEW."teamMessageId" AND m."tenantId"=NEW."tenantId" AND m."planEncrypted" IS NOT NULL AND m.status='SENT' AND e.state='SUCCEEDED') THEN RAISE EXCEPTION 'R12 confirmed message and complete slot admission required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R12_message_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE exec text; class text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'R12 message tombstone retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'SENT' OR NEW.revision<>0 OR NEW."payloadEncrypted" IS NULL OR NEW."planEncrypted" IS NULL OR NEW."payloadErasedAt" IS NOT NULL THEN RAISE EXCEPTION 'R12 initial immutable message plan required' USING ERRCODE='23514'; END IF;
  IF NEW."attachmentId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "TeamAttachment" a JOIN "ActionExecution" e ON e.id=a."finalizeExecutionId" AND e."tenantId"=a."tenantId"
   WHERE a.id=NEW."attachmentId" AND a."tenantId"=NEW."tenantId" AND a."ownerUserId"=NEW."senderUserId" AND a.state='SEALED' AND e.state='SUCCEEDED' AND a."payloadErasedAt" IS NULL) THEN RAISE EXCEPTION 'R12 exact finalized owned attachment required' USING ERRCODE='23514'; END IF;
  exec=NEW."sendExecutionId";class='send_team_message';
 ELSIF NEW."payloadEncrypted" IS NULL AND NEW."planEncrypted" IS NULL AND OLD."payloadErasedAt" IS NULL AND NEW."payloadErasedAt" IS NOT NULL
  AND (to_jsonb(NEW)-ARRAY['payloadEncrypted','planEncrypted','payloadErasedAt'])=(to_jsonb(OLD)-ARRAY['payloadEncrypted','planEncrypted','payloadErasedAt'])
  AND "RC_payload_claim"(OLD."tenantId",'TeamMessage',OLD.id,OLD."planHash",LEAST(OLD."expiresAt",COALESCE(OLD."withdrawnAt",OLD."expiresAt")),'purge_team_message_payloads','team-lifecycle-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY(SELECT id FROM "ActionExecution" WHERE "tenantId"=OLD."tenantId" AND (id=OLD."sendExecutionId" OR id=OLD."withdrawalExecutionId" OR "teamMessageId"=OLD.id))) THEN RETURN NEW;
 ELSE
  IF OLD.status<>'SENT' OR NEW.status<>'WITHDRAWN' OR NEW.revision<>OLD.revision+1
   OR (to_jsonb(NEW)-ARRAY['status','revision','withdrawnAt','withdrawnByUserId','withdrawalExecutionId','withdrawalIdentityHash','withdrawalIntentHash'])<>(to_jsonb(OLD)-ARRAY['status','revision','withdrawnAt','withdrawnByUserId','withdrawalExecutionId','withdrawalIdentityHash','withdrawalIntentHash']) THEN RAISE EXCEPTION 'R12 explicit own withdrawal only' USING ERRCODE='23514'; END IF;
  exec=NEW."withdrawalExecutionId";class='withdraw_team_message';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM "ActionExecution" e JOIN "Membership" m ON m."userId"=e."actorUserId" AND m."tenantId"=e."tenantId" JOIN "User" u ON u.id=m."userId"
  WHERE e.id=exec AND e."tenantId"=NEW."tenantId" AND e."actorUserId"=NEW."senderUserId" AND e."actionClass"=class
   AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW' AND m.status='active' AND u.status='active'
   AND m.role IN ('tenant_owner','business_owner','tenant_admin','administrator','staff')) THEN RAISE EXCEPTION 'R12 current admitted sender required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_execution_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE root "ExpenseReminderRun"%ROWTYPE; root_xid xid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."expenseReminderRunId" IS NOT NULL THEN RAISE EXCEPTION 'R13 slot tombstone retained' USING ERRCODE='23514'; END IF; RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW."expenseReminderRunId" IS DISTINCT FROM OLD."expenseReminderRunId" OR NEW."expenseReminderSlotKey" IS DISTINCT FROM OLD."expenseReminderSlotKey" THEN
   RAISE EXCEPTION 'R13 immutable slot binding' USING ERRCODE='23514';
  END IF; RETURN NEW;
 END IF;
 IF NEW."expenseReminderRunId" IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO root FROM "ExpenseReminderRun" WHERE id=NEW."expenseReminderRunId" AND "tenantId"=NEW."tenantId";
 SELECT xmin INTO root_xid FROM "ExpenseReminderRun" WHERE id=root.id;
 IF root.id IS NULL OR root_xid<>pg_current_xact_id()::xid OR root."intentEncrypted" IS NULL OR NEW.state<>'READY'
  OR NEW."policyDecision"<>'ALLOW' OR NEW."dryRun" OR NEW."intentExpiresAt" IS DISTINCT FROM (root."expiresAt" AT TIME ZONE 'UTC') THEN
  RAISE EXCEPTION 'R13 complete same-transaction weekly admission required' USING ERRCODE='23514';
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_intake_complete"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE n integer; lo integer; hi integer;
BEGIN
 SELECT count(*),min("itemIndex"),max("itemIndex") INTO n,lo,hi FROM "ExpenseIntakeBinding"
  WHERE "tenantId"=NEW."tenantId" AND "sourceNamespace"=NEW."sourceNamespace" AND "sourceEventHash"=NEW."sourceEventHash";
 IF n<>NEW."sourceItemCount" OR lo<>0 OR hi<>n-1 THEN RAISE EXCEPTION 'R13 full frozen card bundle required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R13_intake_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior "ExpenseIntakeBinding"%ROWTYPE; prior_xid xid; approval_xid xid;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'R13 source binding is immutable' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('r13-intake/'||NEW."tenantId"||'/'||NEW."sourceNamespace"||'/'||NEW."sourceEventHash",0));
 SELECT * INTO prior FROM "ExpenseIntakeBinding" WHERE "tenantId"=NEW."tenantId" AND "sourceNamespace"=NEW."sourceNamespace" AND "sourceEventHash"=NEW."sourceEventHash" LIMIT 1;
 IF prior.id IS NOT NULL THEN
  SELECT xmin INTO prior_xid FROM "ExpenseIntakeBinding" WHERE id=prior.id;
  IF prior_xid<>pg_current_xact_id()::xid OR
   (to_jsonb(prior)-ARRAY['id','itemIndex','approvalRequestId'])<>(to_jsonb(NEW)-ARRAY['id','itemIndex','approvalRequestId']) THEN
   RAISE EXCEPTION 'R13 no late append / conflicting source bundle' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT xmin INTO approval_xid FROM "AiApprovalRequest" WHERE id=NEW."approvalRequestId" AND "tenantId"=NEW."tenantId";
 IF approval_xid IS NULL OR approval_xid<>pg_current_xact_id()::xid OR NOT EXISTS (
  SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId"
   JOIN "AuthIdentity" a ON a.id=NEW."authIdentityId" AND a."tenantId"=m."tenantId" AND a."userId"=m."userId" AND a.provider='telegram'
   JOIN "AiApprovalRequest" q ON q.id=NEW."approvalRequestId" AND q."tenantId"=m."tenantId" AND q."requestedByUserId"=m."userId"
  WHERE m.id=NEW."actorMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."actorUserId"
   AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner')
   AND q."toolName"='expenses.create' AND q.status='pending' AND q."encryptedArguments" IS NOT NULL
   AND q."expiresAt"=q."createdAt"+interval '10 minutes') THEN
  RAISE EXCEPTION 'R13 exact source principal and atomic existing approval required' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public."R14_cash_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous "CashDeclaration"%ROWTYPE; class text;
BEGIN
 IF TG_OP='INSERT' THEN
  class=CASE WHEN NEW.revision=1 THEN 'declare_cash_position' ELSE 'correct_cash_position' END;
  IF NEW."countedAt">clock_timestamp() OR (NEW.revision>1 AND (NEW."encryptedReason" IS NULL OR length(NEW."encryptedReason")=0)) OR NOT EXISTS (
   SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId" JOIN "ActionExecution" e ON e.id=NEW."actionExecutionId" AND e."tenantId"=NEW."tenantId"
   WHERE m.id=NEW."declaredByMembershipId" AND m."tenantId"=NEW."tenantId" AND m."userId"=NEW."declaredByUserId"
    AND m.status='active' AND u.status='active' AND m.role IN ('tenant_owner','business_owner','accountant')
    AND (m."branchId" IS NULL OR m."branchId"=NEW."branchId")
    AND e."actorUserId"=NEW."declaredByUserId" AND e."actionClass"=class AND e.state='EXECUTING' AND NOT e."dryRun" AND e."policyDecision"='ALLOW') THEN
   RAISE EXCEPTION 'R14 exact admitted declaration actor/observation required' USING ERRCODE='23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('r14/'||NEW."tenantId"||'/'||NEW."branchId"||'/'||NEW."businessDay",0));
  SELECT * INTO previous FROM "CashDeclaration" WHERE "tenantId"=NEW."tenantId" AND "branchId"=NEW."branchId" AND "businessDay"=NEW."businessDay" ORDER BY revision DESC LIMIT 1;
  IF (previous.id IS NULL AND (NEW.revision<>1 OR NEW."previousDeclarationId" IS NOT NULL)) OR
    (previous.id IS NOT NULL AND (NEW."previousDeclarationId" IS DISTINCT FROM previous.id OR NEW.revision<>previous.revision+1)) THEN
   RAISE EXCEPTION 'R14 stale exact branch/day predecessor' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD."encryptedReason" IS NOT NULL AND NEW."encryptedReason" IS NULL
  AND (to_jsonb(NEW)-'encryptedReason')=(to_jsonb(OLD)-'encryptedReason')
  AND "RC_payload_claim"(OLD."tenantId",'CashDeclaration',OLD.id,OLD."intentHash",OLD."createdAt"+interval '7 years','purge_cash_declaration_reason_payloads','package5.r14.cash-declaration-retention')
  AND "RC_execution_set_resolved"(OLD."tenantId",ARRAY[OLD."actionExecutionId"])
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'R14 immutable cash history / exact scoped reason claim required' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public."RC_confirmed_owner_receipt"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item jsonb; ref text;
BEGIN
 item=to_jsonb(NEW); ref=item->>TG_ARGV[0];
 IF ref IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "ActionExecution" e
  WHERE e.id=ref AND e."tenantId"=item->>'tenantId' AND e.state='SUCCEEDED'
   AND NOT e."dryRun" AND e."policyDecision"='ALLOW'
   AND e."reconciliationState" IN ('NOT_REQUIRED','RESOLVED')) THEN
  RAISE EXCEPTION 'R-C owner mutation requires the same committed canonical receipt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.a18_guard_security_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE execution_ref TEXT;
BEGIN
  IF TG_TABLE_NAME='ClientConsentInvalidation' THEN
    PERFORM a18_assert_security_outcome(NEW."tenantId",NEW."actionExecutionId");
  ELSIF TG_TABLE_NAME='ActionExecution' THEN
    IF NEW."actionClass"='invalidate_client_consent_authority' AND NEW.state::text='SUCCEEDED' THEN
      PERFORM a18_assert_security_outcome(NEW."tenantId",NEW.id);
    END IF;
  ELSIF NEW."revocationEvidenceJson"->>'reason'='UNPROVEN_CLIENT_PROVENANCE' THEN
    SELECT i."actionExecutionId" INTO execution_ref FROM "ClientConsentInvalidation" i
      WHERE i."tenantId"=NEW."tenantId" AND i."invalidatedLinkId"=NEW.id LIMIT 1;
    PERFORM a18_assert_security_outcome(NEW."tenantId",execution_ref);
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.b35_graph_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c "MarketingCampaign"%ROWTYPE; r "MarketingCampaignRecipient"%ROWTYPE;
 a "MarketingAudience"%ROWTYPE; e "ActionExecution"%ROWTYPE; n INTEGER; m INTEGER;
 campaign_id TEXT; tid TEXT; route JSONB; slotrow RECORD; leaf RECORD;
BEGIN
 tid:=NEW."tenantId";
 IF TG_TABLE_NAME='MarketingCampaign' THEN campaign_id:=NEW.id;
 ELSIF TG_TABLE_NAME='MarketingCampaignRecipient' THEN campaign_id:=NEW."campaignId";
 ELSE
  SELECT mc.id INTO campaign_id FROM "MarketingCampaign" mc WHERE mc."actionExecutionId"=NEW.id AND mc."tenantId"=tid;
  IF campaign_id IS NULL AND NEW.capability IN ('communication.bulk-campaign.admit.v2','communication.bulk-slot.admit.v2')
   AND NEW.state NOT IN ('PENDING_APPROVAL','NOT_EXECUTED') THEN
   RAISE EXCEPTION 'B35 admission requires exact durable graph' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT * INTO c FROM "MarketingCampaign" WHERE "MarketingCampaign".id=campaign_id AND "tenantId"=tid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF c."lifecycleVersion"=2 THEN
  SELECT * INTO a FROM "MarketingAudience" WHERE "MarketingAudience".id=c."audienceId" AND "tenantId"=tid;
  IF a."snapshotContract" IS DISTINCT FROM 'maya.bulk-client-audience/1' OR a.status IS DISTINCT FROM 'FROZEN'
    OR a."snapshotHash" IS DISTINCT FROM c."audienceSnapshotHash" OR a."eligibleCount"<>c."recipientCount" THEN
   RAISE EXCEPTION 'B35 exact sealed audience required' USING ERRCODE='23514';
  END IF;
  IF c."confirmedAt" IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO e FROM "ActionExecution" WHERE "ActionExecution".id=c."actionExecutionId" AND "tenantId"=tid;
  IF e.capability IS DISTINCT FROM 'communication.bulk-campaign.admit.v2' OR e."actionClass" IS DISTINCT FROM 'deliver_bulk_campaign'
   OR e."targetRef" IS DISTINCT FROM c.id OR e."approvalDecision" IS DISTINCT FROM 'APPROVED'
   OR e."approvalDecidedByUserId" IS DISTINCT FROM c."confirmedByUserId" OR e."approvalDecidedAt" IS DISTINCT FROM c."confirmedAt"
   OR NOT COALESCE(e."evidenceRefsJson" @> jsonb_build_array('b35:intent:'||c."bulkIntentHash"),false) THEN
   RAISE EXCEPTION 'B35 matching immutable Action Engine approval required' USING ERRCODE='23514';
  END IF;
  IF EXISTS (
   (SELECT "clientId" FROM "MarketingAudienceRecipient" WHERE "tenantId"=tid AND "audienceId"=c."audienceId"
    EXCEPT SELECT "clientId" FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id AND "lifecycleVersion"=2)
   UNION ALL
   (SELECT "clientId" FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id
    EXCEPT SELECT "clientId" FROM "MarketingAudienceRecipient" WHERE "tenantId"=tid AND "audienceId"=c."audienceId")
  ) THEN RAISE EXCEPTION 'B35 approved audience/Client child set must be equal' USING ERRCODE='23514'; END IF;
  -- Verify references only at first seal, not on later revocation/reconciliation.
  IF TG_TABLE_NAME='MarketingCampaign' AND (TG_OP='INSERT' OR to_jsonb(OLD)->>'confirmedAt' IS NULL) THEN
   FOR r IN SELECT * FROM "MarketingCampaignRecipient" WHERE "tenantId"=tid AND "campaignId"=c.id LOOP
    route:=r."routePlanJson";
    IF route->>'link' IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM "ClientChannelLink" l WHERE l.id=route->'link'->>'id' AND l."tenantId"=tid AND l."clientId"=r."clientId"
      AND l.provider=route->'link'->>'provider' AND l."providerSubjectHash"=route->'link'->>'subjectHash'
      AND l."verificationEvidenceHash"=route->'link'->>'verificationEvidenceHash' AND l."revokedAt" IS NULL
      AND l.provider=CASE route->>'primary' WHEN 'inbox' THEN 'maya_user' ELSE 'telegram' END
    ) THEN RAISE EXCEPTION 'B35 route binding foreign/revoked/mismatched' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(route->'webPushEndpoints') ep WHERE NOT EXISTS (
     SELECT 1 FROM "ClientWebPushEndpoint" p WHERE p.id=ep->>'id' AND p."tenantId"=tid AND p."clientId"=r."clientId"
      AND p."clientChannelLinkId"=ep->>'clientChannelLinkId' AND p."materialHash"=ep->>'materialHash' AND p."endedAt" IS NULL
    )) THEN RAISE EXCEPTION 'B35 Web Push plan foreign/ended/mismatched' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(route->'apnsDevices') d WHERE NOT EXISTS (
     SELECT 1 FROM "DevicePushToken" p WHERE p.id=d->>'id' AND p."tenantId"=tid AND p."userId"=route->>'userId'
    )) THEN RAISE EXCEPTION 'B35 APNs plan foreign/missing' USING ERRCODE='23514'; END IF;
   END LOOP;
  END IF;
  IF c."aggregateState" IN ('COMPLETED','PARTIAL','FAILED','SKIPPED','CANCELLED','EXPIRED') AND EXISTS (
   SELECT 1 FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id
    AND (cr."terminalAt" IS NULL OR cr."aggregateState" IN ('READY','RUNNING','UNRESOLVED'))
  ) THEN RAISE EXCEPTION 'B35 root cannot terminalize pending/UNKNOWN children' USING ERRCODE='23514'; END IF;
  IF c."aggregateState" IN ('COMPLETED','PARTIAL','FAILED','SKIPPED','CANCELLED','EXPIRED') AND c."aggregateState"::text IS DISTINCT FROM (
   SELECT CASE WHEN count(*)=0 THEN 'SKIPPED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='COMPLETED')=count(*) THEN 'COMPLETED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='FAILED')=count(*) THEN 'FAILED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='CANCELLED')=count(*) THEN 'CANCELLED'
    WHEN count(*) FILTER (WHERE cr."aggregateState"='EXPIRED')=count(*) THEN 'EXPIRED'
    WHEN count(*) FILTER (WHERE cr."aggregateState" IN ('SKIPPED','CANCELLED','EXPIRED'))=count(*) THEN 'SKIPPED'
    ELSE 'PARTIAL' END
   FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id
  ) THEN RAISE EXCEPTION 'B35 root outcome must project actual Client outcomes' USING ERRCODE='23514'; END IF;
 ELSIF c."parentRecipientId" IS NOT NULL THEN
  SELECT * INTO r FROM "MarketingCampaignRecipient" WHERE "MarketingCampaignRecipient".id=c."parentRecipientId" AND "tenantId"=tid;
  IF r."lifecycleVersion" IS DISTINCT FROM 2 OR NOT EXISTS (
   SELECT 1 FROM "MarketingCampaign" p WHERE p.id=r."campaignId" AND p."tenantId"=tid AND p."lifecycleVersion"=2 AND p."confirmedAt" IS NOT NULL
  ) OR NOT EXISTS (SELECT 1 FROM b35_slots(r."routePlanJson") s WHERE s.slot=c."bulkSlotKey" AND s.channel=c.channel) THEN
   RAISE EXCEPTION 'B35 transport must fill an originally approved slot' USING ERRCODE='23514';
  END IF;
  SELECT * INTO e FROM "ActionExecution" WHERE "ActionExecution".id=c."actionExecutionId" AND "tenantId"=tid;
  IF e.capability IS DISTINCT FROM 'communication.bulk-slot.admit.v2' OR e."actionClass" IS DISTINCT FROM 'deliver_bulk_campaign'
    OR e."targetRef" IS DISTINCT FROM r.id OR NOT COALESCE(e."evidenceRefsJson" @> jsonb_build_array('b35:slot:'||c."bulkSlotKey"),false) THEN
   RAISE EXCEPTION 'B35 transport admission binding mismatch' USING ERRCODE='23514';
  END IF;
  SELECT count(*) INTO n FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id;
  IF n<>c."recipientCount" THEN RAISE EXCEPTION 'B35 transport leaf set must match exact pinned count' USING ERRCODE='23514'; END IF;
  FOR leaf IN SELECT * FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id LOOP
   IF (CASE c.channel
    WHEN 'inbox' THEN leaf."recipientKind"='internal_user' AND leaf."internalUserId"=r."routePlanJson"->>'userId'
      AND leaf."eligibilityEvidenceRef"='b35:link:'||(r."routePlanJson"->'link'->>'id')
    WHEN 'telegram' THEN leaf."recipientKind"='telegram_chat' AND leaf."internalUserId" IS NULL
      AND leaf."eligibilityEvidenceRef"='b35:link:'||(r."routePlanJson"->'link'->>'id')
    WHEN 'apns' THEN leaf."recipientKind"='device_token' AND leaf."internalUserId"=r."routePlanJson"->>'userId'
      AND leaf."eligibilityEvidenceRef"='b35:device:'||substring(c."bulkSlotKey" FROM 6)
    WHEN 'web_push' THEN leaf."recipientKind"='client_web_push_endpoint' AND leaf."internalUserId" IS NULL AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(r."routePlanJson"->'webPushEndpoints') ep
       WHERE leaf."eligibilityEvidenceRef"='b35:endpoint:'||(ep->>'id'))
    ELSE false END) IS NOT TRUE THEN
    RAISE EXCEPTION 'B35 leaf must retain exact planned endpoint reference' USING ERRCODE='23514';
   END IF;
  END LOOP;
  IF (SELECT count(DISTINCT cr."eligibilityEvidenceRef") FROM "MarketingCampaignRecipient" cr WHERE cr."tenantId"=tid AND cr."campaignId"=c.id) <> c."recipientCount" THEN
   RAISE EXCEPTION 'B35 duplicate endpoint leaf forbidden' USING ERRCODE='23514'; END IF;
  IF c.channel='web_push' THEN
   IF c."recipientCount" <> jsonb_array_length(r."routePlanJson"->'webPushEndpoints') THEN
    RAISE EXCEPTION 'B35 exact pinned Web Push fanout required' USING ERRCODE='23514'; END IF;
  ELSIF c."recipientCount"<>1 THEN RAISE EXCEPTION 'B35 single fixed transport recipient required' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.guard_b31_booking_intent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."bookingIntentContract" IS NOT NULL AND EXISTS (SELECT 1 FROM "Tenant" WHERE id = OLD."tenantId") THEN
      RAISE EXCEPTION 'B31 booking identity cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."bookingIntentContract" IS NOT NULL AND NEW."bookingIntentEncrypted" IS NULL THEN
      RAISE EXCEPTION 'B31 accepted intent requires encrypted snapshot' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  -- This also prevents installing an invented fingerprint on a legacy row.
  IF NEW."bookingIntentContract" IS DISTINCT FROM OLD."bookingIntentContract"
     OR NEW."bookingIntentHash" IS DISTINCT FROM OLD."bookingIntentHash"
     OR (OLD."bookingIntentContract" IS NOT NULL AND
       (NEW."tenantId", NEW.id, NEW."normalizedInputContract", NEW."normalizedInputHash", NEW."identityFingerprint",
        NEW."capability", NEW."actionClass", NEW."targetRef", NEW."transportIdempotencyKey") IS DISTINCT FROM
       (OLD."tenantId", OLD.id, OLD."normalizedInputContract", OLD."normalizedInputHash", OLD."identityFingerprint",
        OLD."capability", OLD."actionClass", OLD."targetRef", OLD."transportIdempotencyKey")) THEN
    RAISE EXCEPTION 'B31 accepted booking intent is immutable; no historical backfill' USING ERRCODE = '23514';
  END IF;
  IF NEW."bookingIntentEncrypted" IS DISTINCT FROM OLD."bookingIntentEncrypted"
     OR (OLD."bookingIntentContract" IS NOT NULL AND NEW."normalizedInputEncrypted" IS DISTINCT FROM OLD."normalizedInputEncrypted") THEN
    IF (NEW."bookingIntentEncrypted" IS DISTINCT FROM OLD."bookingIntentEncrypted" AND NEW."bookingIntentEncrypted" IS NOT NULL)
       OR (NEW."normalizedInputEncrypted" IS DISTINCT FROM OLD."normalizedInputEncrypted" AND NEW."normalizedInputEncrypted" IS NOT NULL)
       OR OLD."bookingIntentContract" IS NULL
       OR NEW.state::TEXT NOT IN ('SUCCEEDED', 'FAILED', 'NOT_EXECUTED')
       OR NEW."payloadRetentionUntil" IS NULL OR NEW."payloadRetentionUntil" > CURRENT_TIMESTAMP THEN
      RAISE EXCEPTION 'B31 snapshot permits only terminal retention cleanup' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.require_b31_execution_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW."bookingIntentContract" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "ActionExecutionIdempotencyBinding" WHERE "actionExecutionId" = NEW.id AND "tenantId" = NEW."tenantId"
  ) THEN
    RAISE EXCEPTION 'B31 execution and first binding must commit atomically' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$
